INSERT INTO exam_questions (subject, grade, question_type, question_text, options, answer, explanation, difficulty, topic)
VALUES
  ('สุขศึกษา', 'ป.4', 'mcq', 'เกณฑ์ที่ใช้วัดการเจริญเติบโตทางร่างกายของนักเรียนในเบื้องต้นคือข้อใด', '["น้ำหนักและส่วนสูง","ขนาดของรอบศีรษะ","ความยาวของเส้นผม","จำนวนฟันน้ำนม"]'::jsonb, '0'::jsonb, 'การชั่งน้ำหนักและวัดส่วนสูงตามเกณฑ์มาตรฐานอายุและเพศ เป็นวิธีประเมินการเจริญเติบโตทางร่างกายที่ถูกต้องและแม่นยำ', 'easy', '[พ 1.1 ป.4/1] การเจริญเติบโตตามวัย'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'อวัยวะใดทำหน้าที่เป็นโครงร่างพยุงร่างกายและป้องกันอวัยวะภายในจากอันตราย', '["กระดูก","ผิวหนัง","กล้ามเนื้อ","เส้นเลือด"]'::jsonb, '0'::jsonb, 'กระดูกทำหน้าที่เป็นแกนค้ำจุนร่างกาย เป็นที่ยึดเกาะของกล้ามเนื้อ และช่วยปกป้องอวัยวะภายใน เช่น กะโหลกศีรษะปกป้องสมอง ซี่โครงปกป้องหัวใจและปอด', 'easy', '[พ 1.1 ป.4/2] ระบบกล้ามเนื้อและกระดูก'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'สารอาหารชนิดใดที่มีความจำเป็นต่อการเสริมสร้างความแข็งแรงของกระดูกและฟันมากที่สุด', '["แคลเซียม (จากนมและปลาตัวเล็ก)","ไขมันอิ่มตัว","วิตามินซี","น้ำตาลทราย"]'::jsonb, '0'::jsonb, 'แร่ธาตุแคลเซียมและฟอสฟอรัสมีบทบาทสำคัญในการสร้างมวลกระดูกและฟันให้แข็งแรง', 'easy', '[พ 1.1 ป.4/3] การดูแลรักษากระดูกและข้อต่อ'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'ข้อใดเป็นลักษณะของ ''เพื่อนที่ดี''', '["คอยช่วยเหลือเมื่อเดือดร้อนและชวนกันทำความดี","ชวนกันโดดเรียนไปเล่นเกม","ล้อเลียนปมด้อยของเพื่อน","ยุยงให้เพื่อนทะเลาะกัน"]'::jsonb, '0'::jsonb, 'เพื่อนที่ดีคือกัลยาณมิตรที่คอยตักเตือน ช่วยเหลือเกื้อกูล และชักชวนกันไปในทางที่สร้างสรรค์และถูกต้อง', 'easy', '[พ 2.1 ป.4/1] ลักษณะของเพื่อนที่ดี'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'หากมีคนแปลกหน้ามาสัมผัสร่างกายในจุดที่ไม่เหมาะสมและพยายามชวนไปในที่ลับตาคน เราควรทำอย่างไร', '["ปฏิเสธเสียงดัง วิ่งหนี และรีบบอกพ่อแม่หรือครูทันที","ยอมตามไปเพราะเกรงใจ","รับขนมหรือเงินจากเขา","เก็บเงียบไว้คนเดียว"]'::jsonb, '0'::jsonb, 'หลักความปลอดภัยคือ ''ปฏิเสธ วิ่งหนี ขอความช่วยเหลือ และบอกผู้ใหญ่ที่ไว้วางใจทันที'' (Say NO, Run away, Tell someone)', 'easy', '[พ 2.1 ป.4/3] การป้องกันการถูกล่วงละเมิดทางเพศ'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'กิจกรรมในข้อใดจัดเป็น ''การเคลื่อนไหวร่างกายแบบอยู่กับที่'' (Non-locomotor)', '["การก้มแตะปลายเท้าและยืนบิดตัว","การวิ่งผลัด 50 เมตร","การกระโดดข้ามรั้ว","การขี่จักรยาน"]'::jsonb, '0'::jsonb, 'การเคลื่อนไหวอยู่กับที่คือการเคลื่อนไหวอวัยวะส่วนต่างๆ โดยที่ฐานของร่างกายไม่ได้เคลื่อนย้ายตำแหน่ง เช่น บิดตัว ก้มแตะ เหยียดแขน', 'easy', '[พ 3.1 ป.4/1] การเคลื่อนไหวร่างกายแบบอยู่กับที่'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'กิจกรรมในข้อใดจัดเป็น ''การเคลื่อนไหวร่างกายแบบเคลื่อนที่'' (Locomotor)', '["การวิ่งเหยาะๆ และการกระโดดเขย่ง","การยืนแขม่วท้อง","การนั่งแกว่งแขน","การยืนทรงตัวขาเดียว"]'::jsonb, '0'::jsonb, 'การวิ่ง การเดิน การกระโดดข้าม เป็นการเคลื่อนย้ายตำแหน่งร่างกายจากจุดหนึ่งไปยังอีกจุดหนึ่ง', 'easy', '[พ 3.1 ป.4/2] การเคลื่อนไหวแบบเคลื่อนที่'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'คำกล่าวว่า ''รู้แพ้ รู้ชนะ รู้อภัย'' หมายถึงคุณลักษณะใด', '["การมีน้ำใจนักกีฬา","การต้องการเป็นที่หนึ่งเสมอ","การยอมแพ้ตั้งแต่ยังไม่เริ่มแข่ง","การเกี่ยงให้ผู้อื่นเล่น"]'::jsonb, '0'::jsonb, 'น้ำใจนักกีฬาคือการยอมรับผลการแข่งขันเมื่อแพ้ ภาคภูมิใจอย่างสุภาพเมื่อชนะ และให้อภัยต่อข้อผิดพลาดในการเล่น', 'easy', '[พ 3.2 ป.4/1] น้ำใจนักกีฬา'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'อาหารในข้อใดจัดอยู่ในกลุ่ม ''โปรตีน'' ที่ช่วยซ่อมแซมส่วนที่สึกหรอของร่างกาย', '["เนื้อหมู ปลา ไข่ไก่ นมสด","ข้าวสวย ขนมปัง เผือก มัน","น้ำมันพืช เนย กะทิ","ผักบุ้ง ตำลึง คะน้า"]'::jsonb, '0'::jsonb, 'โปรตีนได้จากเนื้อสัตว์ ไข่ นม และถั่วเมล็ดแห้ง มีหน้าที่เสริมสร้างกล้ามเนื้อและซ่อมแซมเนื้อเยื่อส่วนที่สึกหรอ', 'easy', '[พ 4.1 ป.4/1] อาหารหลัก 5 หมู่ (โปรตีน)'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'สัญลักษณ์ ''หวาน มัน เค็ม'' (GDA) บนซองขนม มีไว้เพื่อเตือนให้ผู้บริโภคระมัดระวังสารอาหารใด', '["น้ำตาล ไขมัน และโซเดียม","โปรตีน วิตามิน และเกลือแร่","ใยอาหารและแป้ง","แคลเซียมและธาตุเหล็ก"]'::jsonb, '0'::jsonb, 'ฉลาก GDA แสดงปริมาณพลังงาน น้ำตาล (หวาน) ไขมัน (มัน) และโซเดียม (เค็ม) เพื่อป้องกันโรคเรื้อรัง', 'easy', '[พ 4.1 ป.4/2] ฉลากโภชนาการ'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'สัตว์ชนิดใดเป็นพาหะนำเชื้อไวรัสเดงกีที่ทำให้เกิด ''โรคไข้เลือดออก''', '["ยุงลาย","ยุงก้นปล่อง","แมลงวัน","หนูท่อ"]'::jsonb, '0'::jsonb, 'ยุงลายบ้านและยุงลายสวนที่ออกหากินในเวลากลางวัน เป็นพาหะนำโรคไข้เลือดออก', 'easy', '[พ 4.1 ป.4/3] การป้องกันโรคไข้เลือดออก'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'สุขบัญญัติแห่งชาติข้อที่ 1 ระบุให้ดูแลรักษาสิ่งใด', '["ดูแลรักษาร่างกายและของใช้ให้สะอาด","รักษาฟันให้แข็งแรงและแปรงฟันทุกวัน","ล้างมือก่อนกินอาหารและหลังขับถ่าย","กินอาหารสุกสะอาด"]'::jsonb, '0'::jsonb, 'สุขบัญญัติข้อ 1 คือ ''ดูแลรักษาร่างกายและของใช้ให้สะอาด'' เช่น การอาบน้ำ สระผม ตัดเล็บ และสวมใส่เสื้อผ้าที่สะอาด', 'easy', '[พ 4.1 ป.4/4] สุขบัญญัติแห่งชาติข้อที่ 1'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อต้องการข้ามถนนในบริเวณที่มีการจราจรหนาแน่น ควรข้ามถนนที่จุดใดจึงปลอดภัยที่สุด', '["สะพานลอยคนข้าม หรือทางม้าลาย","วิ่งตัดหน้ารถยนต์ที่กำลังชะลอตัว","ข้ามตรงทางโค้ง","มุดลอดเกาะกลางถนน"]'::jsonb, '0'::jsonb, 'สะพานลอยคนข้ามเป็นจุดข้ามที่ปลอดภัยที่สุด รองลงมาคือทางม้าลายที่มีสัญญาณไฟคนข้าม', 'easy', '[พ 5.1 ป.4/1] ความปลอดภัยจากการจราจร'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'สารเสพติดและสารพิษอันตรายที่พบในควันบุหรี่ที่ทำลายปอดและทำให้เกิดโรคมะเร็งปอดคือสารใด', '["นิโคติน และ น้ำมันทาร์","คาเฟอีน","แอลกอฮอล์","กลูโคส"]'::jsonb, '0'::jsonb, 'ในควันบุหรี่มีสารนิโคติน (ทำให้เสพติด) และสารทาร์หรือน้ำมันดิน (สารก่อมะเร็งปอดและถุงลมโป่งพอง)', 'easy', '[พ 5.1 ป.4/2] โทษของบุหรี่'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อมี ''เลือดกำเดาไหล'' วิธีปฐมพยาบาลที่ถูกต้องที่สุดคือข้อใด', '["นั่งก้มหน้าเล็กน้อย แล้วใช้นิ้วบีบปีกจมูกทั้งสองข้างไว้ประมาณ 5-10 นาที","เงยหน้าขึ้นให้สูงที่สุด","สั่งน้ำมูกแรงๆ","นอนหงายราบไปกับพื้น"]'::jsonb, '0'::jsonb, 'การนั่งก้มหน้าเล็กน้อยและบีบปีกจมูกจะช่วยให้เลือดหยุดไหล และป้องกันไม่ให้เลือดไหลย้อนลงคอจนสำลัก (ห้ามเงยหน้าเพราะเสี่ยงสำลักเลือด)', 'easy', '[พ 5.1 ป.4/3] การปฐมพยาบาลเลือดกำเดาไหล'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'กล้ามเนื้อหัวใจ แตกต่างจากกล้ามเนื้อลาย (กล้ามเนื้อแขนขา) อย่างไรในด้านการทำงาน', '["กล้ามเนื้อหัวใจทำงานอยู่นอกเหนืออำนาจจิตใจโดยอัตโนมัติตลอดเวลา","กล้ามเนื้อหัวใจสั่งให้หยุดเต้นได้ตามใจชอบ","กล้ามเนื้อหัวใจไม่มีวันเหนื่อยล้าเพราะไม่มีเส้นประสาท","กล้ามเนื้อหัวใจทำงานเฉพาะเวลานอนหลับ"]'::jsonb, '0'::jsonb, 'กล้ามเนื้อหัวใจทำงานแบบอัตโนมัติ (Involuntary muscle) นอกเหนือการควบคุมของจิตใจ เต้นสูบฉีดเลือดตลอดชีวิต', 'medium', '[พ 1.1 ป.4/2] ชนิดของกล้ามเนื้อในร่างกาย'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'การยกของหนักจากพื้นอย่างถูกวิธีเพื่อป้องกันการบาดเจ็บของกระดูกสันหลังควรปฏิบัติอย่างไร', '["ย่อเข่าลงให้หลังตรง แล้วใช้แรงจากกล้ามเนื้อขาส่งตัวขึ้น","ก้มตัวลงโดยไม่งอเข่าแล้วออกแรงดึงด้วยหลัง","บิดเอวขณะยกของหนัก","ยกของด้วยมือข้างเดียว"]'::jsonb, '0'::jsonb, 'ท่ายกของที่ถูกต้องคือเข้าใกล้สิ่งของ ย่อเข่า หลังตรง แล้วใช้แรงยกจากกล้ามเนื้อขาแทนการก้มหลัง', 'medium', '[พ 1.1 ป.4/3] ท่าทางการใช้ชีวิตที่ถูกต้องเพื่อรักษากระดูกสันหลัง'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อรุ่นพี่ชวนไปสูบบุหรี่ไฟฟ้าหลังโรงเรียน ควรใช้ทักษะการปฏิเสธอย่างไรจึงจะปลอดภัยและเด็ดขาด', '["ปฏิเสธด้วยน้ำเสียงหนักแน่นและสุภาพว่า ''ไม่ครับ/ค่ะ'' แล้วรีบเดินเลี่ยงออกมาทันที","พูดจาท้าทายและด่าว่ารุ่นพี่","ลองสูบดูสักครั้งเพื่อไม่ให้เสียหน้า","ยืนนิ่งๆ ไม่พูดอะไร"]'::jsonb, '0'::jsonb, 'การปฏิเสธสิ่งเสพติดต้องใช้การสื่อสารที่ชัดเจน เด็ดขาด ไม่ลังเล ปฏิเสธซ้ำหากถูกเซ้าซี้ และพาตนเองออกจากสถานการณ์เสี่ยงทันที', 'medium', '[พ 2.1 ป.4/2] การปฏิเสธและทักษะชีวิต'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'ข้อใดเป็นพฤติกรรมที่ช่วยสร้างความอบอุ่นและความเข้าใจอันดีในครอบครัว', '["รับประทานอาหารร่วมกันและพูดคุยแลกเปลี่ยนเรื่องราวในแต่ละวันด้วยเหตุผล","ต่างคนต่างเล่นโทรศัพท์มือถือขณะอยู่ด้วยกัน","เก็บตัวอยู่แต่ในห้องนอนคนเดียว","ใช้อารมณ์ตัดสินปัญหาเมื่อเกิดความขัดแย้ง"]'::jsonb, '0'::jsonb, 'การใช้เวลาร่วมกัน การพูดคุยรับฟัง และการช่วยเหลือแบ่งเบาภาระงานบ้าน เป็นพื้นฐานสร้างครอบครัวที่อบอุ่น', 'medium', '[พ 2.1 ป.4/1] การสร้างสัมพันธภาพในครอบครัว'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'กิจกรรมในข้อใดเป็นการเคลื่อนไหวที่ต้องใช้ ''ทักษะการควบคุมอุปกรณ์''', '["การเลี้ยงลูกฟุตบอลซิกแซ็กหลบกรวย","การกระโดดตบ 20 ครั้ง","การนอนหงายปั่นจักรยานกลางอากาศ","การวิ่งกลับตัว 10 เมตร"]'::jsonb, '0'::jsonb, 'การเลี้ยง ส่ง โยน เตะ ลูกบอล จัดเป็นการเคลื่อนไหวแบบใช้อุปกรณ์ (Manipulative skills) ที่ต้องอาศัยการประสานสัมพันธ์ของตา มือ และเท้า', 'medium', '[พ 3.1 ป.4/3] การเคลื่อนไหวร่างกายแบบใช้อุปกรณ์ (Manipulative)'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เหตุใดจึงต้องทำการ ''อบอุ่นร่างกาย'' (Warm-up) และยืดเหยียดกล้ามเนื้อก่อนเล่นกีฬาทุกครั้ง', '["เพื่อเพิ่มอุณหภูมิร่างกาย ยืดหยุ่นกล้ามเนื้อ และลดความเสี่ยงจากการบาดเจ็บ","เพื่อใช้เวลาให้หมดชั่วโมง","เพื่อทำให้รู้สึกเหนื่อยล้าก่อนแข่ง","เพื่อทำให้นักกีฬาตัวสูงขึ้น"]'::jsonb, '0'::jsonb, 'การ Warm-up ช่วยเตรียมความพร้อมของหัวใจ การไหลเวียนเลือด และเพิ่มความยืดหยุ่นของกล้ามเนื้อและข้อต่อเพื่อป้องกันการฉีกขาด', 'medium', '[พ 3.1 ป.4/4] การอบอุ่นร่างกาย (Warm-up)'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อกรรมการตัดสินว่าเราทำฟาวล์ในระหว่างการแข่งขันกีฬา ข้อใดเป็นการปฏิบัติตนที่ถูกต้องตามมารยาทนักกีฬา', '["ยอมรับคำตัดสินของกรรมการด้วยความเคารพและสงบอารมณ์","วิ่งเข้าไปโต้เถียงและด่าทอกรรมการ","หยุดเล่นและเดินออกจากสนามทันที","แกล้งทำร้ายผู้เล่นฝ่ายตรงข้าม"]'::jsonb, '0'::jsonb, 'การเคารพคำตัดสินของกรรมการถือเป็นหัวใจสำคัญของกฎกติกาสากลและมารยาทของนักกีฬาที่ดี', 'medium', '[พ 3.2 ป.4/2] การปฏิบัติตามกฎกติกาการแข่งขัน'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'ตามหลัก ''ธงโภชนาการ'' ของคนไทย กลุ่มอาหารที่ควรกินในปริมาณมากที่สุดในแต่ละวันคือกลุ่มใด', '["กลุ่มข้าว-แป้ง","กลุ่มผักและผลไม้","กลุ่มเนื้อสัตว์และนม","กลุ่มน้ำมัน น้ำตาล และเกลือ"]'::jsonb, '0'::jsonb, 'ฐานกว้างที่สุดของธงโภชนาการคือกลุ่มข้าว-แป้ง ให้พลังงานหลักแก่ร่างกาย ควรกินวันละ 8-12 ทัพพี', 'medium', '[พ 4.1 ป.4/1] ธงโภชนาการ (สัดส่วนอาหาร)'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'คนที่มีปัญหาเรื่องระบบขับถ่าย ท้องผูกเป็นประจำ ควรเลือกรับประทานอาหารกลุ่มใดเพิ่มขึ้น', '["ผักใบเขียวและผลไม้ที่มีกากใยอาหารสูง (Fiber)","เนื้อสัตว์ติดมันและของทอด","น้ำอัดลมและขนมเค้ก","ข้าวเหนียวหน้าสังขยา"]'::jsonb, '0'::jsonb, 'ใยอาหาร (Dietary fiber) ในผักและผลไม้ช่วยเพิ่มกากอาหาร กระตุ้นการบีบตัวของลำไส้ใหญ่ ช่วยให้ขับถ่ายสะดวกและป้องกันอาการท้องผูก', 'medium', '[พ 4.1 ป.4/1] อาหารหมู่ที่ 3 และ 4 (วิตามินและเกลือแร่)'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'ข้อความ ''EXP 15/12/26'' บนกล่องอาหารสำเร็จรูป หมายความว่าอย่างไร', '["อาหารนี้หมดอายุวันที่ 15 ธันวาคม ค.ศ. 2026 ไม่ควรรับประทานหลังจากวันนี้","อาหารนี้ผลิตเมื่อวันที่ 15 ธันวาคม 2026","ควรบริโภคก่อนวันที่ 15 ธันวาคม","ราคาอาหาร 15 บาท ลดเหลือ 12 บาท"]'::jsonb, '0'::jsonb, 'EXP ย่อมาจาก Expiry date หมายถึง วันหมดอายุ หลังจากวันที่ระบุคุณภาพอาหารจะเสื่อมลงและอาจเป็นอันตราย ไม่ควรบริโภค', 'medium', '[พ 4.1 ป.4/2] การอ่านวันหมดอายุบนฉลากอาหาร'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'มาตรการ ''5 ป. 1 ข.'' เพื่อป้องกันยุงลายวางไข่ ข้อใดคือ ''ป. ปิด''', '["ปิดฝาภาชนะกักเก็บน้ำให้มิดชิด","ปิดประตูหน้าต่างบ้านตลอด 24 ชั่วโมง","ปิดไฟในห้องนอน","ปิดปากและจมูก"]'::jsonb, '0'::jsonb, '5 ป. ได้แก่ ปิด (ปิดฝาภาชนะน้ำ), เปลี่ยน (เปลี่ยนน้ำทุก 7 วัน), ปล่อย (ปล่อยปลากินลูกน้ำ), ปรับปรุง (ปรับสิ่งแวดล้อม), และปฏิบัติเป็นประจำ', 'medium', '[พ 4.1 ป.4/3] มาตรการ 5 ป. ป้องกันไข้เลือดออก'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'การสวมหน้ากากอนามัย และล้างมือด้วยสบู่บ่อยๆ ช่วยป้องกันโรคติดต่อข้อใดได้ดีที่สุด', '["โรคไข้หวัดใหญ่ และ โควิด-19","โรคไข้เลือดออก","โรคมาลาเรีย","โรคพิษสุนัขบ้า"]'::jsonb, '0'::jsonb, 'ไข้หวัดใหญ่และโควิด-19 ติดต่อผ่านละอองฝอยจากการไอจามและการสัมผัสเชื้อ การสวมหน้ากากและล้างมือจึงป้องกันได้โดยตรง', 'medium', '[พ 4.1 ป.4/3] การป้องกันโรคติดต่อทางเดินหายใจ (ไข้หวัด)'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'ข้อควรระวังสำคัญที่สุดในการเสียบปลั๊กหรือเปิดสวิตช์เครื่องใช้ไฟฟ้าคือข้อใด', '["มือและเท้าต้องแห้งสนิท ไม่เปียกน้ำ","ต้องเปิดเพลงก่อนเสียบปลั๊ก","ต้องใช้สายไฟที่เก่าและขาด","ต้องเสียบเครื่องใช้ไฟฟ้าพร้อมกันหลายๆ เครื่องในเต้ารับเดียว"]'::jsonb, '0'::jsonb, 'น้ำเป็นตัวนำไฟฟ้าที่ดี หากมือเปียกน้ำขณะสัมผัสปลั๊กไฟอาจทำให้กระแสไฟฟ้ารั่วไหลเข้าสู่ร่างกายจนถูกไฟดูดถึงแก่ชีวิตได้', 'medium', '[พ 5.1 ป.4/1] ความปลอดภัยจากการใช้เครื่องใช้ไฟฟ้า'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'สารระเหย เช่น กาว ทินเนอร์ น้ำมันเบนซิน เมื่อสูดดมเข้าไปจะทำลายอวัยวะส่วนใดโดยตรงและรุนแรงที่สุด', '["ทำลายเซลล์สมองและระบบประสาทส่วนกลาง","ทำลายเล็บมือและเล็บเท้า","ทำลายเส้นผม","ทำลายข้อต่อหัวเข่า"]'::jsonb, '0'::jsonb, 'สารระเหยประกอบด้วยสารไฮโดรคาร์บอนที่เป็นพิษ เมื่อสูดดมจะเข้าสู่กระแสเลือดไปทำลายเซลล์สมอง ทำให้สมองฝ่อ ความจำเสื่อม และเสียชีวิตได้', 'medium', '[พ 5.1 ป.4/2] สารเสพติดประเภทสารระเหย'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อเกิดอุบัติเหตุหกล้ม ข้อเท้าแพลง หรือมีรอยฟกช้ำ ในช่วง 24 ชั่วโมงแรกควรปฐมพยาบาลอย่างไร', '["ประคบด้วยความเย็น (น้ำแข็งหรือเจลเย็น) เพื่อลดอาการบวมและเลือดออกใต้ผิวหนัง","ประคบด้วยน้ำร้อนจัดทันที","นวดคลึงแรงๆ บริเวณที่บวม","ทายาหม่องร้อนๆ"]'::jsonb, '0'::jsonb, 'ในช่วง 24 ชั่วโมงแรกต้องประคบเย็นเพื่อให้เส้นเลือดหดตัว ลดการบวมและระงับความเจ็บปวด (ห้ามประคบร้อนเพราะจะทำให้เส้นเลือดขยายตัวและบวมขึ้น)', 'medium', '[พ 5.1 ป.4/3] การปฐมพยาบาลแผลฟกช้ำ'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'นักเรียนระดับชั้น ป.4 (อายุ 9-10 ปี) มักมีลักษณะพัฒนาการทางสังคมข้อใดที่เด่นชัด', '["ให้ความสำคัญกับกลุ่มเพื่อนและชอบทำกิจกรรมร่วมกับเพื่อนวัยเดียวกัน","ติดแม่และไม่ยอมไปโรงเรียน","ชอบอยู่คนเดียวเงียบๆ ไม่สนใจใคร","ไม่ต้องการมีเพื่อน"]'::jsonb, '0'::jsonb, 'เด็กวัย 9-10 ปีเริ่มก้าวเข้าสู่วัยเด็กตอนปลาย จะเริ่มให้ความสำคัญกับกลุ่มเพื่อน (Peer group) ต้องการการยอมรับจากกลุ่ม และชอบเล่นเป็นทีม', 'medium', '[พ 1.1 ป.4/1] พัฒนาการทางอารมณ์และสังคมในวัยเรียน'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'การแปรงฟันตามสูตร ''2-2-2'' ของกรมอนามัย มีความหมายอย่างไร', '["แปรงฟันวันละ 2 ครั้ง, แปรงนานอย่างน้อย 2 นาที, และงดกินอาหารหลังแปรงฟัน 2 ชั่วโมง","แปรงฟัน 2 นาที, ใช้น้ำยาบ้วนปาก 2 ขวด, เปลี่ยนแปรงสีฟันทุก 2 วัน","แปรงฟันวันละ 2 หน, แปรง 2 ซี่, บ้วนปาก 2 ครั้ง","แปรงฟันเช้า 2 นาที เย็น 2 นาที"]'::jsonb, '0'::jsonb, 'สูตร 2-2-2 คือ แปรงฟันด้วยยาสีฟันผสมฟลูออไรด์วันละ 2 ครั้ง, นานครั้งละ 2 นาทีขึ้นไป, และงดรับประทานอาหาร/เครื่องดื่มหลังแปรง 2 ชั่วโมงเพื่อให้ฟลูออไรด์เคลือบฟัน', 'medium', '[พ 4.1 ป.4/4] สุขอนามัยในช่องปากและฟัน'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'สัญลักษณ์รูป ''หัวกะโหลกไขว้'' บนขวดน้ำยาล้างห้องน้ำหรือยาฆ่าแมลง สื่อถึงสิ่งใด', '["สารพิษอันตรายถึงแก่ชีวิต ห้ามรับประทานหรือสัมผัส","ของเล่นเด็ก","อาหารบำรุงสุขภาพ","เครื่องสำอาง"]'::jsonb, '0'::jsonb, 'สัญลักษณ์หัวกะโหลกไขว้เป็นเครื่องหมายเตือนสากลของ ''สารพิษอันตรายร้ายแรง'' (Poison/Toxic) ซึ่งอาจทำให้เสียชีวิตได้', 'medium', '[พ 5.1 ป.4/1] ป้ายความปลอดภัยสารเคมีในบ้าน'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'การทดสอบสมรรถภาพทางกายด้วยท่า ''นั่งงอตัวไปข้างหน้า'' (Sit and Reach) ใช้วัดสมรรถภาพด้านใด', '["ความอ่อนตัวของกล้ามเนื้อหลังและต้นขาด้านหลัง","ความแข็งแรงของกล้ามเนื้อแขน","ความจุปอดและระบบไหลเวียนโลหิต","ความเร็วในการวิ่ง"]'::jsonb, '0'::jsonb, 'การนั่งเหยียดขาแล้วเอื้อมมือแตะหรือเลยปลายเท้า ใช้วัดความยืดหยุ่นหรือความอ่อนตัว (Flexibility) ของข้อต่อและกล้ามเนื้อ', 'medium', '[พ 3.1 ป.4/2] สมรรถภาพทางกาย (ความอ่อนตัว)'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'การที่นักเรียนไม่ไปจับ สัมผัส หรือเปิดกระโปรง/ดึงกางเกงเพื่อนเล่น จัดเป็นคุณธรรมข้อใด', '["การเคารพสิทธิส่วนบุคคลในเนื้อตัวร่างกายของผู้อื่น","ความขลาดกลัว","ความขี้อาย","การไม่เป็นมิตร"]'::jsonb, '0'::jsonb, 'ร่างกายของทุกคนเป็นพื้นที่ส่วนตัวที่ต้องได้รับการเคารพ ห้ามมิให้ผู้ใดมาสัมผัสหรือกลั่นแกล้งโดยไม่ยินยอม', 'medium', '[พ 2.1 ป.4/2] การเคารพสิทธิในร่างกายของตนเองและผู้อื่น'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เด็กที่ดื่มน้ำอัดลม ชานมไข่มุก และกินขนมกรุบกรอบรสหวานมันเค็มเป็นประจำ เสี่ยงต่อปัญหาสุขภาพใดมากที่สุด', '["โรคอ้วน ฟันผุ และเสี่ยงต่อโรคเบาหวาน","โรคขาดสารอาหารรุนแรงจนผอมแห้ง","โรคกระดูกเปราะแต่กำเนิด","โรคตับแข็ง"]'::jsonb, '0'::jsonb, 'การบริโภคน้ำตาลและไขมันเกินความต้องการของร่างกายจะสะสมเป็นไขมันส่วนเกิน นำไปสู่โรคอ้วน ฟันผุ และโรคไม่ติดต่อเรื้อรัง (NCDs)', 'medium', '[พ 4.1 ป.4/1] ภาวะทุพโภชนาการ (โรคอ้วนในเด็ก)'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อถูกผึ้งหรือต่อต่อย ขั้นตอนแรกที่ต้องรีบปฏิบัติคือข้อใด', '["ใช้ขอบบัตรพลาสติกหรือแหนบสะกิดเอาเหล็กในออกอย่างระมัดระวัง","บีบเค้นพิษอย่างรุนแรง","ใช้มีดกรีดปากแผล","ปล่อยทิ้งไว้ไม่ต้องทำอะไร"]'::jsonb, '0'::jsonb, 'ต้องรีบสะกิดเอาเหล็กในออกเพื่อไม่ให้ถุงพิษปล่อยพิษเข้าสู่ร่างกายเพิ่ม จากนั้นล้างด้วยน้ำสบู่และประคบเย็น', 'medium', '[พ 5.1 ป.4/3] การปฐมพยาบาลแมลงสัตว์กัดต่อย'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'การเล่นเกมเบ็ดเตล็ด เช่น ''ลิงชิงบอล'' ช่วยเสริมสร้างทักษะใดมากที่สุด', '["ความคล่องแคล่วว่องไวและการทำงานประสานกันของสายตาและมือ","การนอนหลับลึก","การคำนวณคณิตศาสตร์","การท่องจำคำศัพท์"]'::jsonb, '0'::jsonb, 'ลิงชิงบอลช่วยฝึกการสังเกต การคาดคะเนทิศทางลูกบอล ความว่องไวในการรับ-ส่งบอล และการเคลื่อนที่อย่างรวดเร็ว', 'medium', '[พ 3.2 ป.4/1] เกมเบ็ดเตล็ดและการฝึกทักษะ'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'หลักการ ''กินร้อน ช้อนกลาง ล้างมือ'' มีจุดประสงค์เพื่อป้องกันโรคกลุ่มใด', '["โรคติดต่อทางเดินอาหาร เช่น ท้องร่วง อาหารเป็นพิษ และอหิวาตกโรค","โรคทางเดินหายใจ","โรคผิวหนัง","โรคติดต่อจากยุง"]'::jsonb, '0'::jsonb, 'อาหารสุกร้อน ช้อนกลาง และการล้างมือก่อนรับประทานอาหาร ช่วยกำจัดเชื้อแบคทีเรียและไวรัสที่ปนเปื้อนในอาหารเข้าสู่ทางเดินอาหาร', 'medium', '[พ 4.1 ป.4/4] สุขอนามัยในการรับประทานอาหาร'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'ข้อควรปฏิบัติเพื่อความปลอดภัยสูงสุดในการลงเล่นน้ำในแม่น้ำหรือทะเลคือข้อใด', '["สวมเสื้อชูชีพทุกครั้งและอยู่ในความดูแลของผู้ใหญ่อย่างใกล้ชิด","ว่ายน้ำตามลำพังในเวลากลางคืน","ลงเล่นน้ำทันทีหลังกินอาหารอิ่ม","เล่นในบริเวณที่มีป้ายเตือนน้ำลึก"]'::jsonb, '0'::jsonb, 'การจมน้ำเป็นสาเหตุการเสียชีวิตอันดับต้นๆ ของเด็กวัยเรียน การสวมเสื้อชูชีพและการมีผู้ดูแลใกล้ชิดช่วยป้องกันอุบัติเหตุได้ดีที่สุด', 'medium', '[พ 5.1 ป.4/1] ความปลอดภัยจากการเล่นน้ำ'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อเราออกแรง ''งอแขน'' ขึ้นมาเพื่อยกของ กล้ามเนื้อต้นแขนด้านหน้า (ไบเซพส์) และกล้ามเนื้อต้นแขนด้านหลัง (ไตรเซพส์) จะทำงานประสานกันอย่างไร', '["กล้ามเนื้อไบเซพส์หดตัว และกล้ามเนื้อไตรเซพส์คลายตัว","กล้ามเนื้อทั้งสองมัดหดตัวพร้อมกัน","กล้ามเนื้อไบเซพส์คลายตัว และกล้ามเนื้อไตรเซพส์หดตัว","กล้ามเนื้อทั้งสองมัดคลายตัวพร้อมกัน"]'::jsonb, '0'::jsonb, 'กล้ามเนื้อลายทำงานเป็นคู่ตรงข้าม (Antagonism): เมื่องอแขน กล้ามเนื้อมัดหน้า (Biceps) จะหดตัวดึงกระดูกแขนขึ้น ขณะที่มัดหลัง (Triceps) จะคลายตัว', 'hard', '[พ 1.1 ป.4/2] การวิเคราะห์การทำงานประสานกันของระบบกล้ามเนื้อและกระดูก'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เด็กชายวินัยมีน้ำหนักเกินเกณฑ์มาตรฐาน (เริ่มอ้วน) ในมื้อกลางวันควรเลือกรับประทานชุดอาหารข้อใดที่ให้สารอาหารครบ 5 หมู่แต่ให้พลังงานและไขมันต่ำที่สุด', '["ก๋วยเตี๋ยวน้ำใสใส่หมูไม่ติดมัน ผักบุ้ง ถั่วงอก ผลไม้ฝรั่ง 1 ผล และน้ำเปล่า","ข้าวราดข้าวมันไก่ทอด น้ำอัดลม 1 กระป๋อง","บะหมี่กึ่งสำเร็จรูปผัดไส้กรอกทอด ขนมปังปิ้งเนยนม","ข้าวไข่เจียวหมูสับทอดน้ำมันเยิ้ม ชานมไข่มุก"]'::jsonb, '0'::jsonb, 'ก๋วยเตี๋ยวน้ำใสให้คาร์โบไฮเดรต โปรตีนไขมันต่ำจากหมูไม่ติดมัน วิตามินเกลือแร่จากผักและฝรั่ง ไม่มีน้ำมันทอดและน้ำตาลจากน้ำอัดลม', 'hard', '[พ 4.1 ป.4/1] การวิเคราะห์และเปรียบเทียบคุณค่าทางโภชนาการ'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'ฉลากขนมระบุ: ''หนึ่งหน่วยบริโภค: 1/2 ซอง (30 กรัม), จำนวนหน่วยบริโภคต่อซอง: 2, พลังงานทั้งหมด 160 กิโลแคลอรีต่อหน่วยบริโภค'' หากนักเรียนรับประทานขนมหมดทั้งซองเพียงคนเดียว จะได้รับพลังงานรวมกี่กิโลแคลอรี', '["320 กิโลแคลอรี","160 กิโลแคลอรี","80 กิโลแคลอรี","240 กิโลแคลอรี"]'::jsonb, '0'::jsonb, 'หนึ่งหน่วยบริโภคคือครึ่งซอง (160 kcal) ทั้งซองมี 2 หน่วยบริโภค ดังนั้นเมื่อกินหมดทั้งซองจะได้รับพลังงาน = 160 × 2 = 320 กิโลแคลอรี', 'hard', '[พ 4.1 ป.4/2] การคำนวณและประเมินฉลากโภชนาการ'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เด็กหญิงมาลีมีไข้สูงเฉียบพลัน ปวดศีรษะ ปวดเมื่อยตามกระบอกตา มีจุดเลือดออกสีแดงเล็กๆ ตามแขนขา คลื่นไส้อาเจียน แต่วัดไข้แล้วไม่มีน้ำมูกไหลหรือเจ็บคอ น่าจะสงสัยว่าเป็นโรคใด และควรปฏิบัติตนอย่างไร', '["สงสัยโรคไข้เลือดออก ควรรีบไปพบแพทย์ทันที และห้ามรับประทานยาลดไข้กลุ่มแอสไพรินหรือไอบูโพรเฟน","เป็นโรคหวัดธรรมดา ให้ซื้อยาแอสไพรินมากินเอง","เป็นโรคกระเพาะอาหาร ให้กินยาลดกรด","เป็นโรคลมแดด ให้ไปออกกำลังกายกลางแจ้ง"]'::jsonb, '0'::jsonb, 'ไข้สูงลอย ปวดกระบอกตา มีจุดเลือดออก ไม่มีน้ำมูก เป็นอาการบ่งชี้ของโรคไข้เลือดออก ห้ามกินยาแอสไพรินเพราะจะทำให้เลือดออกในทางเดินอาหารรุนแรงถึงชีวิตได้', 'hard', '[พ 4.1 ป.4/3] การวินิจฉัยอาการและการแพร่ระบาดของโรค'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อพบเพื่อนถูกงูไม่ทราบชนิดกัดที่บริเวณข้อเท้า วิธีการปฐมพยาบาลที่ถูกต้องตามหลักการแพทย์ในปัจจุบันคือข้อใด', '["ล้างแผลด้วยน้ำสะอาด ให้ผู้บาดเจ็บอยู่นิ่งๆ ดามขาให้อยู่ต่ำกว่าระดับหัวใจ และรีบนำส่งโรงพยาบาลพร้อมจดจำลักษณะงู","ใช้เชือกรัดเหนือแผลให้แน่นที่สุดจนเลือดหยุดไหล (ขันชะเนาะ)","ใช้ปากดูดพิษงูออกจากบาดแผล","ใช้มีดกรีดปากแผลเป็นรูปกากบาทแล้วโรยด้วยยาผง"]'::jsonb, '0'::jsonb, 'การปฐมพยาบาลงูกัดสมัยใหม่: ห้ามขันชะเนาะ ห้ามกรีดแผล ห้ามดูดพิษ ให้ล้างแผล อยู่นิ่งๆ เพื่อชะลอการกระจายของพิษ และรีบไป รพ. ฉีดเซรุ่ม', 'hard', '[พ 5.1 ป.4/3] การปฐมพยาบาลกรณีถูกงูกัด'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เมื่อได้ยินสัญญาณเตือนภัยไฟไหม้ดังขึ้นในอาคารเรียน นักเรียนควรปฏิบัติตนตามขั้นตอนใดอย่างถูกต้องและปลอดภัยที่สุด', '["ตั้งสติ ใช้ผ้าชุบน้ำปิดจมูก ก้มตัวต่ำหรือคลานหนีควันไฟ ใช้บันไดหนีไฟไปยังจุดรวมพล และห้ามใช้ลิฟต์เด็ดขาด","รีบวิ่งไปขึ้นลิฟต์เพื่อลงมาชั้นล่างให้เร็วที่สุด","วิ่งกลับไปเก็บกระเป๋าและสิ่งของมีค่าในห้องเรียน","กระโดดออกจากหน้าต่างชั้น 3 ลงมาบนพื้นสนาม"]'::jsonb, '0'::jsonb, 'ควันไฟจะลอยขึ้นสู่ที่สูงจึงต้องก้มตัวต่ำ ใช้ผ้าเปียกกรองควัน ห้ามใช้ลิฟต์เพราะระบบไฟอาจตัดค้าง และรวมพลที่จุดปลอดภัยเพื่อนับจำนวนคน', 'hard', '[พ 5.1 ป.4/1] การวิเคราะห์มาตรการความปลอดภัยในโรงเรียน'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เพื่อนในเกมออนไลน์ที่ไม่เคยเห็นหน้า ชวนเล่นเกมส่งรูปภาพส่วนตัวแลกกับไอเทมหายากในเกม นักเรียนควรวิเคราะห์และตัดสินใจอย่างไร', '["เป็นพฤติกรรมล่อลวงทางเพศออนไลน์ (Online Grooming) ต้องปฏิเสธทันที บล็อกผู้ใช้นั้น และแจ้งผู้ปกครองหรือครู","ส่งรูปถ่ายครึ่งท่อนไปแลกเพราะอยากได้ไอเทม","ชวนเพื่อนคนอื่นมาส่งรูปด้วยกัน","นัดเจอตัวจริงเพื่อขอแลกไอเทมโดยไม่บอกพ่อแม่"]'::jsonb, '0'::jsonb, 'การขอภาพถ่ายส่วนตัวในเกมออนไลน์ถือเป็นภัยคุกคามทางเพศผ่านไซเบอร์ (Online Child Sexual Exploitation) ห้ามส่งภาพเด็ดขาดและต้องแจ้งผู้ใหญ่ทันที', 'hard', '[พ 2.1 ป.4/3] การวิเคราะห์สถานการณ์เสี่ยงภัยทางเพศและการถูกล่อลวง'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'การออกกำลังกายแบบแอโรบิก (เช่น วิ่งเหยาะ ว่ายน้ำ เต้นแอโรบิก ต่อเนื่อง 20-30 นาที) ส่งผลต่อระบบการทำงานของร่างกายอย่างไรมากที่สุด', '["เสริมสร้างความแข็งแรงและความทนทานของกล้ามเนื้อหัวใจ ปอด และระบบไหลเวียนโลหิต","ทำให้กล้ามเนื้อแขนขยายใหญ่ขึ้นใน 1 วัน","ทำให้กระดูกยืดยาวขึ้นทันที 5 เซนติเมตร","ทำให้ร่างกายไม่ต้องใช้ออกซิเจนในการหายใจ"]'::jsonb, '0'::jsonb, 'การออกกำลังกายแบบแอโรบิกเป็นกิจกรรมที่ใช้ออกซิเจนต่อเนื่อง ช่วยให้กล้ามเนื้อหัวใจสูบฉีดเลือดได้มีประสิทธิภาพและเพิ่มความจุปอด', 'hard', '[พ 3.1 ป.4/4] การวิเคราะห์ระบบพลังงานและการออกกำลังกาย'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'การดื่มเครื่องดื่มแอลกอฮอล์จนมึนเมาแล้วขับขี่ยานพาหนะ ก่อให้เกิดผลกระทบร้ายแรงตามข้อใดมากที่สุด', '["ฤทธิ์แอลกอฮอล์กดประสาททำให้การตัดสินใจช้าลง ควบคุมรถไม่ได้ เสี่ยงเกิดอุบัติเหตุจนตนเองและผู้อื่นบาดเจ็บหรือเสียชีวิต","ทำให้รถยนต์ประหยัดน้ำมันมากขึ้น","ทำให้ขับรถได้รวดเร็วและปลอดภัยขึ้น","ทำให้ผู้ขับขี่มีสมาธิในการมองเห็นดีขึ้น"]'::jsonb, '0'::jsonb, 'แอลกอฮอล์มีฤทธิ์กดระบบประสาทส่วนกลาง ทำให้สายตาพร่ามัว การตอบสนองช้าลง การกะระยะผิดพลาด จึงเป็นสาเหตุอันดับหนึ่งของอุบัติเหตุบนท้องถนน', 'hard', '[พ 5.1 ป.4/2] ผลกระทบทางสังคมของสิ่งเสพติด'),
  ('สุขศึกษา', 'ป.4', 'mcq', 'เพราะเหตุใดเด็กในวัยเรียน (ประถมศึกษา) จึงจำเป็นต้องนอนหลับพักผ่อนอย่างน้อยวันละ 8-10 ชั่วโมงในเวลาที่เหมาะสม (ไม่เกิน 21.00-22.00 น.)', '["เพราะโกรทฮอร์โมน (Growth Hormone) ที่ช่วยการเจริญเติบโตและซ่อมแซมร่างกายจะหลั่งได้ดีที่สุดช่วงนอนหลับสนิทในตอนกลางคืน","เพราะจะช่วยให้ไม่ต้องตื่นมากินอาหารเช้า","เพราะจะช่วยให้เล่นเกมในวันรุ่งขึ้นได้นานขึ้น","เพราะระบบหายใจจะหยุดทำงานชั่วคราวขณะหลับ"]'::jsonb, '0'::jsonb, 'ฮอร์โมนการเจริญเติบโต (Growth Hormone) จะหลั่งมากที่สุดในช่วงที่นอนหลับสนิทลึก (Deep Sleep) ช่วงเวลา 22.00 - 02.00 น. ซึ่งจำเป็นต่อการเพิ่มความสูงและการพัฒนาสมองของเด็ก', 'hard', '[พ 1.1 ป.4/3] การประเมินสุขอนามัยการนอนหลับ');
